eAAA;EACA,gCAnkBe;AC4fjB;;AD0EA;EACE,UAAA;EACA,eAAA;EACA,gCAzkBe;ACkgBjB;;AD0EA;EACE,kBAAA;ACvEF;ADyEE;EACE,eAAA;ACvEJ;;AD6EE;;EAEE,cAAA;EACA,eAAA;AC1EJ;;AD8EA;EACE,yBAAA;EACA,mBAAA;EACA,YAAA;EACA,kBAAA;EACA,mBAAA;AC3EF;AD6EE;EACE,qBApmBY;EAqmBZ,gBAAA;AC3EJ;AD8EE;EACE,cAAA;AC5EJ;AD2EE;EACE,cAAA;AC5EJ;;ADgFA;EACE,aAAA;EACA,iBAAA;AC7EF;;ADgFA;EACE,gBAAA;EACA,UAAA;EACA,UAAA;AC7EF;;ADgFA,yBAAA;AAEA;EACE,gBAAA;EACA,SAAA;AC9EF;AD+EE;EACE,mBAAA;EACA,kBAAA;AC7EJ;ADgFE;EACE,gBAAA;EACA,eAAA;EACA,aAAA;AC9EJ;ADgFI;EACE,qBAAA;EACA,YAAA;EACA,kBAAA;EACA,aAAA;EACA,eAAA;AC9EN;ADgFM;EACE,cAAA;AC9ER;ADiFM;EACE,eAAA;AC/ER;ADkFM;EACE,gBAAA;EACA,YAAA;EACA,eAAA;AChFR;;ADsFA,kBAAA;AAEE;EACE,mBAAA;ACpFJ;ADuFE;EACE,0BAAA;ACrFJ;ADwFE;;;;;;EAME,mBAAA;ACtFJ;ADyFE;;EAEE,kBAAA;ACvFJ;AD0FE;EACE,gBAAA;EACA,WAAA;EACA,eAAA;EACA,mBAAA;EACA,yBAAA;ACxFJ;AD0FI;;EAEE,gBAAA;EACA,mBAAA;EACA,yBAAA;ACxFN;AD2FI;EACE,oCAAA;ACzFN;AD4FI;EACE,mBAAA;AC1FN;AD4FM;EACE,2BAAA;AC1FR;AD+FE;EACE,8BAAA;EACA,aAAA;AC7FJ;AD+FI;EACE,gBAAA;EACA,kBAAA;EACA,eAAA;EACA,gBAAA;AC7FN;ADiGE;EACE,kBAAA;EACA,mBAAA;AC/FJ;;ADmGA;EACE,cAAA;EACA,gCAAA;AChGF;ADiGE;EACE,cAxuBY;ACyoBhB;;ADsGA;EACE,YAAA;EACA,aAAA;ACnGF;;ADsGA;EACE,kBAAA;EACA,qBAAA;EACA,YAAA;EACA,aAAA;ACnGF;ADqGE;EACE,kBAAA;EACA,MAAA;EACA,OAAA;EACA,WAAA;EACA,YAAA;EACA,+BAAA;EACA,mCAAA;EACA,6BAAA;ACnGJ;ADqGI;EACE,UAAA;EACA,sCAAA;ACnGN;ADsGI;EACE,UAAA;EACA,sCAAA;ACpGN;ADuGI;EACE,UAAA;EACA,sCAAA;ACrGN;;AD0GA;EACE;IACE,yBAAA;ECvGF;EDyGA;IACE,yBAAA;ECvGF;AACF;AD0GA;EACE,kBAAA;EACA,WAAA;EACA,sBAAA,EAAA,sBAAA;EACA,SAAA;EACA,gBAAA;EACA,mBAAA;ACxGF;;AD2GA;EACE,kBAAA;EACA,MAAA;EACA,OAAA;EACA,WAAA;EACA,YAAA;ACxGF;;AD2GA;EACE,YAAA,EAAA,0BAAA;EACA,WAAA,EAAA,wCAAA;EACA,sBAAA;KAAA,mBAAA,EAAA,sDAAA;EACA,qBAAA,EAAA,iCAAA;ACxGF;;AD2GA;EACE,kBAAA;ACxGF;;AD2GA;EACE,mFAAA;EACA,0EAAA;EACA,4BAAA;EACA,oBAAA;EACA,8BAAA;EACA,sBAAA;ACxGF;;AD2GA;EACE,gBAAA;ACxGF;;AD2GA;EACI,0BAAA;ACxGJ;;AD4GA;EACE,eAAA;EACA,gBAAA;ACzGF;;AD4GA;EACE,iBAAA,EAAA,qCAAA;EACA,gBAAA,EAAA,6BAAA;ACzGF;;AD4GA;EACE,aAAA;EACA,mBAAA;EACA,mBAAA;ACzGF;;AD4GA;EACE,aAAA;EACA,mBAAA;EACA,mBAAA;ACzGF;;AD4GA;EACE,gBAAA;ACzGF;;ADiHA;EACE,mBAAA;EACA,aAAA;EACA,qBAAA;EACA,iBAAA;EACA,qBAAA;AC9GF;;ADiHA;EACI,gBAAA;EACA,gBAAA;EACA,iBAAA;AC9GJ","file":"style.css","sourcesContent":["@use 'sass:color';\n@import \"mixins\";\n\n@font-face {\n  font-family: 'Mont-Regular';\n  src: url('../fonts/MONT-REGULAR.TTF') format('truetype');\n  font-weight: normal;\n  font-style: normal;\n  font-display: swap;\n}\n\n@font-face {\n  font-family: 'Mont-Light';\n  src: url('../fonts/MONT-LIGHT.TTF') format('truetype');\n  font-weight: normal;\n  font-style: normal;\n  font-display: swap;\n}\n\n// Variables\n$primary-font: \"Mont-Regular\", sans-serif;\n$secondary-font: \"Mont-Light\", serif;\n$primary-color: #f9a743;\n$icon-font: \"themefisher-font\" !important;\n\n/*--\n    Common Css\n--*/\nhtml {\n  overflow-x: hidden;\n}\nbody {\n  font-family: 'MyFont', sans-serif;\n  font-size: 14px;\n  font-weight: 300;\n  line-height: 25px;\n  color: #3b4045;\n  font-family: $primary-font;\n  -webkit-font-smoothing: antialiased;\n}\n\n.preloader {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: #fff;\n  z-index: 999999;\n}\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  font-weight: 300;\n  margin: 0px;\n}\n\nh1,\n.h1 {\n  font-size: 44px;\n  line-height: 56px;\n}\n\nh2,\n.h2 {\n  font-size: 30px;\n  line-height: 35px;\n}\n\nh3,\n.h3 {\n  font-size: 23px;\n  line-height: 25px;\n}\n\nh4,\n.h4 {\n  font-size: 20px;\n  line-height: 24px;\n  font-weight: 400;\n}\n\np {\n  font-size: 18px;\n  line-height: 25px;\n}\n\nul {\n  padding: 0;\n  margin: 0;\n  list-style: none;\n}\n\na {\n  -webkit-transition: all 0.2s ease-in-out 0s;\n  -moz-transition: all 0.2s ease-in-out 0s;\n  -o-transition: all 0.2s ease-in-out 0s;\n  transition: all 0.2s ease-in-out 0s;\n}\n\n.mt-100 {\n  margin-top: 100px;\n}\n\n.bg-1 {\n  background-image: url(../images/call-to-action.jpg);\n}\n\n.bg-orange {\n  // background: $primary-color;\n    background: linear-gradient(\n      to bottom,\n      #ffffff 0%,\n      $primary-color 10%,\n      $primary-color 90%,\n      #ffffff 100%\n    );\n\n\n}\n\n.bg-opacity {\n  position: relative;\n\n  &:before {\n    content: \"\";\n    position: absolute;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    background: rgba(0, 0, 0, 0.7);\n  }\n}\n\na:focus,\n.btn:focus,\n.btn:active:focus {\n  box-shadow: none;\n  outline: 0 none;\n}\n\na,\na:active,\na:focus,\na:active {\n  text-decoration: none;\n}\n\n.section {\n  padding: 40px 0;\n}\n\n.font-size-60 {\n  font-size: 60px;\n  line-height: 1.2;\n\n  @include mobile {\n    font-size: 40px;\n  }\n}\n\n.mb-10 {\n  margin-bottom: 10px;\n}\n\n.mb-40 {\n  margin-bottom: 40px;\n}\n\n.slick-slide {\n  outline: 0;\n}\n\n/*--\n    custom heading\n--*/\n.text-center {\n  text-align: center;\n}\n\n.heading {\n  text-align: center;\n  color: #777777;\n  padding-bottom: 70px;\n\n  h2 {\n    color: #3c3c3c;\n    padding-bottom: 15px;\n    text-transform: capitalize;\n    font-weight: 700;\n    font-size: 40px;\n    line-height: 40px;\n  }\n\n  p {\n    font-size: 17px;\n    line-height: 24px;\n    font-weight: 300;\n  }\n}\n\n.subheading {\n  color: #3c3c3c;\n  padding-bottom: 15px;\n  text-transform: capitalize;\n  font-weight: 500;\n  font-size: 32px;\n  line-height: 45px;\n}\n\n.btn {\n  border-radius: 0;\n  text-decoration: none !important;\n}\n\n.btn-main {\n  color: #fff;\n  border-radius: 30px;\n  font-size: 18px;\n  padding: 15px 40px;\n  display: inline-block;\n  background-color: $primary-color;\n  box-shadow: 0 15px 40px rgba(249, 167, 68, 0.5);\n  background-image: linear-gradient(\n    bottom,\n    rgba(255, 239, 206, 0) 0%,\n    rgba(255, 239, 206, 0.25) 100%\n  );\n\n  &:hover,\n  &:focus {\n    background-color: $primary-color;\n    color: #fff;\n  }\n}\n\n.btn-main-sm {\n  padding: 12px 35px;\n  text-transform: uppercase;\n  font-size: 14px;\n  font-weight: bold;\n}\n\n/* navigation */\n.navbar {\n  &-brand {\n    color: #444;\n    font-size: 25px;\n    margin: 0;\n    line-height: 1;\n  }\n}\n\n.nav-link {\n  font-size: 16px;\n  font-weight: bold;\n  padding: 10px 20px !important;\n}\n\n.navbar-light .navbar-nav .nav-link {\n  color: #444;\n}\n\n.lang-list {\n  border: 0;\n  margin: 10px 20px;\n  font-size: 16px;\n  cursor: pointer;\n}\n\n.navigation {\n  .dropdown-menu {\n    padding: 0px;\n    border: 0;\n    border-radius: 0px;\n    background-color: #f5f5f5;\n\n    @include desktop {\n      text-align: center;\n      float: left !important;\n      width: 100%;\n      margin: 0;\n    }\n\n    li:first-child {\n      margin-top: 5px;\n    }\n\n    li:last-child {\n      margin-bottom: 5px;\n    }\n  }\n\n  .dropdown-toggle::after {\n    display: none;\n  }\n  .dropdown-toggle > i {\n    font-size: 14px;\n  }\n\n  .dropleft .dropdown-menu,\n  .dropright .dropdown-menu {\n    margin: 0;\n  }\n\n  .dropleft .dropdown-toggle::before,\n  .dropright .dropdown-toggle::after {\n    font-weight: bold;\n    font-family: \"themefisher-font\";\n    border: 0;\n    font-size: 10px;\n    vertical-align: 1px;\n    display: inline-block;\n  }\n\n  .dropleft .dropdown-toggle::before {\n    margin-right: 5px;\n    content: \"\\f124\";\n  }\n\n  .dropright .dropdown-toggle::after {\n    margin-left: 5px;\n    content: \"\\f125\";\n  }\n\n  .dropdown-item {\n    color: #444;\n    padding: 0.6rem 1rem 0.35rem;\n    font-weight: 600;\n    font-size: 15px;\n  }\n\n  .dropdown-submenu.active > .dropdown-toggle,\n  .dropdown-submenu:hover > .dropdown-item,\n  .dropdown-item.active,\n  .dropdown-item:hover {\n    background: $primary-color;\n    color: white;\n  }\n\n  @media (min-width: 992px) {\n    .dropdown-menu {\n      transition: all 0.2s ease-in, visibility 0s linear 0.2s,\n        transform 0.2s linear;\n      display: block;\n      visibility: hidden;\n      opacity: 0;\n      min-width: 200px;\n      margin-top: 8px;\n\n      li:first-child {\n        margin-top: 10px;\n      }\n\n      li:last-child {\n        margin-bottom: 10px;\n      }\n    }\n\n    .dropleft .dropdown-menu,\n    .dropright .dropdown-menu {\n      margin-top: -9px;\n    }\n\n    .dropdown:hover > .dropdown-menu {\n      visibility: visible;\n      transition: all 0.45s ease 0s;\n      opacity: 1;\n    }\n  }\n}\n\n.navbar-collapse.show {\n  overflow-y: auto;\n  overflow-x: hidden;\n  max-height: calc(100vh - 80px);\n}\n.navbar-toggler:focus {\n  outline: 0;\n}\n\n/* cart */\n.cart {\n  background: transparent;\n  border: 0;\n  position: relative;\n  i {\n    font-size: 20px;\n  }\n\n  @include desktop {\n    position: absolute;\n    top: 23px;\n    right: 90px;\n  }\n\n  .badge {\n    position: absolute;\n    top: -5px;\n    border-radius: 50%;\n    right: -10px;\n  }\n  &:focus {\n    outline: 0;\n  }\n}\n\n.badge-primary {\n  background-color: $primary-color;\n}\n\n/*--\n    Feature-list start\n--*/\n.feature-list {\n  .btn-main {\n    margin-top: 15px;\n  }\n}\n\n/*--\n  Gallery start\n--*/\n.gallery {\n\n  .owl-item {\n    overflow: hidden;\n    position: relative;\n  }\n\n  .block {\n    padding: 20px;\n    position: relative;\n\n    &:hover .gallery-overlay {\n      transform: scale(1);\n      opacity: 1;\n      border-radius: 0;\n    }\n  }\n\n  .gallery-overlay {\n    position: absolute;\n    bottom: 15px;\n    left: 15px;\n    right: 15px;\n    top: 15px;\n    background: rgba(255, 255, 255, 0.85);\n    text-decoration: none;\n    color: inherit;\n    -webkit-transform: scale(0.7);\n    transform: scale(0.7);\n    -webkit-transition: 0.3s ease-in-out;\n    transition: 0.3s ease-in-out;\n    z-index: 2;\n    opacity: 0;\n    border-radius: 50%;\n\n    .gallery-popup {\n      text-align: center;\n      position: absolute;\n      top: 50%;\n      left: 50%;\n      -webkit-transform: translate(-50%, -50%);\n      -ms-transform: translate(-50%, -50%);\n      transform: translate(-50%, -50%);\n      background: $primary-color;\n      padding: 5px 10px;\n      border-radius: 40px;\n      width: 50px;\n      height: 50px;\n\n      i {\n        color: #fff;\n        font-size: 30px;\n        line-height: 40px;\n        display: inline-block;\n      }\n    }\n  }\n}\n\n/*--\n    service start\n--*/\n.testimonials {\n  .testimonial-block {\n\n    background: lightyellow;\n    padding: 10px 10px;\n\n    border-radius: 15px;\n\n    i {\n      font-size: 40px;\n      display: inline-block;\n      margin-bottom: 20px;\n      color: $primary-color;\n    }\n\n    p {\n      font-family: $secondary-font;\n      font-size: 14px;\n      color: #777;\n    }\n\n    .author-details {\n      margin-top: 30px;\n\n      img {\n        border-radius: 50%;\n        width: 50px;\n      }\n\n      h4 {\n        font-weight: 700;\n        font-size: 20px;\n        margin-top: 10px;\n      }\n    }\n  }\n}\n\n/*--\n    call-to-action start\n--*/\n.call-to-action {\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n  background-size: cover;\n  padding-top: 70px\n}\n\n.input-group {\n  margin-top: 30px;\n  position: relative;\n\n  .btn-submit {\n    padding: 10.5px 40px !important;\n    position: absolute;\n    border-top-left-radius: 0;\n    border-bottom-left-radius: 0;\n    top: 0;\n    right: 0;\n  }\n\n  input {\n    height: 50px;\n    border-radius: 40px;\n    border: none;\n    padding-left: 15px;\n    box-shadow: none;\n    display: table-cell;\n  }\n}\n\n.footer-menu {\n  a {\n    font-size: 14;\n    font-weight: 700;\n    color: #444;\n    padding: 10px;\n  }\n}\n\nfooter {\n  text-align: center;\n  background: #f4f4f4;\n  padding: 25px 0px;\n\n  .footer-logo {\n    color: #555;\n    display: block;\n  }\n\n  p.copyright-text {\n    font-weight: 300;\n    font-size: 12px;\n    color: #888;\n    letter-spacing: 3px;\n    margin-top: 15px;\n\n    a {\n      color: #282828;\n\n      &:hover {\n        text-decoration: none;\n      }\n    }\n  }\n}\n\n// product single\np.price {\n  font-size: 30px;\n  font-family: $secondary-font;\n}\n\ns.price {\n  color: red;\n  font-size: 25px;\n  font-family: $secondary-font;\n}\n\n.product-info {\n  text-align: center;\n\n  .price {\n    font-size: 100%;\n  }\n}\n\n// contact list\n.contact-list {\n  li,\n  a {\n    color: #282828;\n    font-size: 18px;\n  }\n}\n\n.form-control {\n  border: 1px solid #dadada;\n  border-radius: 35px;\n  height: 50px;\n  padding-left: 20px;\n  padding-right: 20px;\n\n  &:focus {\n    border-color: $primary-color;\n    box-shadow: none;\n  }\n\n  &::placeholder {\n    font-size: 80%;\n  }\n}\n\ntextarea.form-control {\n  height: 150px;\n  padding-top: 15px;\n}\n\n.sticky-image {\n  position: sticky;\n  top: 100px;\n  z-index: 1;\n}\n\n/* product sinngle page */\n\n.product-image-slider {\n  position: sticky;\n  top: 80px;\n  .slick-list {\n    margin-bottom: 10px;\n    border-radius: 5px;\n  }\n\n  .slick-dots {\n    margin-top: 10px;\n    padding-left: 0;\n    display: flex;\n\n    li {\n      list-style-type: none;\n      margin: 10px;\n      border-radius: 5px;\n      padding: 10px;\n      cursor: pointer;\n\n      &:first-child {\n        margin-left: 0;\n      }\n\n      &:last-child {\n        margin-right: 0;\n      }\n\n      img {\n        max-height: 80px;\n        height: auto;\n        max-width: 100%;\n      }\n    }\n  }\n}\n\n/* content style */\n.content {\n  * {\n    margin-bottom: 20px;\n  }\n\n  a {\n    text-decoration: underline;\n  }\n\n  h1,\n  h2,\n  h3,\n  h4,\n  h5,\n  h6 {\n    margin-bottom: 10px;\n  }\n\n  ol,\n  ul {\n    padding-left: 10px;\n  }\n\n  table {\n    text-align: left;\n    width: 100%;\n    max-width: 100%;\n    margin-bottom: 1rem;\n    border: 1px solid #dee2e6;\n\n    th,\n    td {\n      padding: 0.75rem;\n      vertical-align: top;\n      border: 1px solid #dee2e6;\n    }\n\n    thead {\n      background: color.adjust(#dadada, $lightness: -2%);\n    }\n\n    tbody {\n      background: #dadada;\n\n      td {\n        text-align: left !important;\n      }\n    }\n  }\n\